import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); m = int(data[1])
    a = [int(x) for x in data[2:2+n]]
    b = [int(x) for x in data[2+n:2+2*n]]

    S = n + 1
    INF = 10**18

    # M[i][j] = min cost of processing one block of n brackets
    # starting at balance i and ending at balance j (balance in [0, n])
    M = [[INF]*S for _ in range(S)]
    for s in range(S):
        dp = [INF]*S
        dp[s] = 0
        for k in range(n):
            ak = a[k]; bk = b[k]
            ndp = [INF]*S
            for bal in range(S):
                v = dp[bal]
                if v >= INF:
                    continue
                if bal + 1 < S:
                    t = v + ak
                    if t < ndp[bal+1]:
                        ndp[bal+1] = t
                if bal > 0:
                    t = v + bk
                    if t < ndp[bal-1]:
                        ndp[bal-1] = t
            dp = ndp
        M[s] = dp

    def mul(A, B):
        C = [[INF]*S for _ in range(S)]
        for i in range(S):
            Ai = A[i]
            Ci = C[i]
            for k in range(S):
                aik = Ai[k]
                if aik >= INF:
                    continue
                Bk = B[k]
                for j in range(S):
                    bkj = Bk[j]
                    if bkj >= INF:
                        continue
                    v = aik + bkj
                    if v < Ci[j]:
                        Ci[j] = v
            C[i] = Ci
        return C

    # identity in (min,+)
    R = [[INF]*S for _ in range(S)]
    for i in range(S):
        R[i][i] = 0

    e = m
    base = M
    while e > 0:
        if e & 1:
            R = mul(R, base)
        e >>= 1
        if e:
            base = mul(base, base)

    print(R[0][0])

main()
