import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    if m > n:
        n, m = m, n
    full = (1 << m) - 1

    def spread(x):
        return (x | (x << 1) | (x >> 1)) & full

    pc = [bin(i).count('1') for i in range(1 << m)]

    dp = {}
    for mask in range(1 << m):
        key = (mask, spread(mask))
        v = pc[mask]
        if key not in dp or dp[key] > v:
            dp[key] = v

    for _ in range(1, n):
        ndp = {}
        for (pm, cov), c in dp.items():
            for new in range(1 << m):
                if (cov | new) != full:
                    continue
                key = (new, spread(new) | pm)
                v = c + pc[new]
                if key not in ndp or ndp[key] > v:
                    ndp[key] = v
        dp = ndp

    best = None
    for (pm, cov), c in dp.items():
        if cov == full:
            if best is None or c < best:
                best = c
    print(n * m - best)

main()
